-- Temporary users and Storage metadata only; no real photo bytes or notifications. All changes roll back.
begin;
create temporary table switch_test(a uuid,b uuid,c uuid,d uuid,s1 uuid,s2 uuid,s3 uuid,code text,photo uuid,note uuid);
insert into switch_test values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,null,null,null,gen_random_uuid(),gen_random_uuid());
insert into auth.users(id,aud,role,email) select a,'authenticated','authenticated',a::text||'@switch-test.invalid' from switch_test union all select b,'authenticated','authenticated',b::text||'@switch-test.invalid' from switch_test union all select c,'authenticated','authenticated',c::text||'@switch-test.invalid' from switch_test union all select d,'authenticated','authenticated',d::text||'@switch-test.invalid' from switch_test;
grant select,update on switch_test to authenticated;
create function pg_temp.assert_switch(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAILED: %',label;end if;end$$;
set local role authenticated;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from switch_test;
update switch_test set s1=public.create_partner_space_with_role('user_1');
update switch_test set code=public.issue_pair_code()->>'code';
insert into storage.objects(bucket_id,name) select 'pipo-shared-images',s1::text||'/'||photo::text||'.jpg' from switch_test;
select public.mutate_shared_record(note,s1,'appreciation',null,null,jsonb_build_object('kind','Locket','message','Old couple photo','taskTitle','','picture','cloud:'||s1::text||'/'||photo::text||'.jpg','at',1),0,gen_random_uuid(),false) from switch_test;
select public.save_care_share(s1,true,'{"cycle":28,"duration":5,"logs":[]}'::jsonb,0) from switch_test;
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true) from switch_test;
select public.redeem_pair_code_with_role(code,'user_2') from switch_test;
select pg_temp.assert_switch((select count(*) from storage.objects where bucket_id='pipo-shared-images' and name=(select s1::text||'/'||photo::text||'.jpg' from switch_test))=1,'original partner sees image metadata');
select pg_temp.assert_switch((select count(*) from public.shared_records where id=(select note from switch_test))=1,'original partner sees Locket');
select public.leave_partner_space();
select pg_temp.assert_switch((select count(*) from public.space_members)=0,'leaving removes both memberships');
select pg_temp.assert_switch((select count(*) from public.shared_records)=0,'old records disappear for leaver');
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from switch_test;
select pg_temp.assert_switch((select count(*) from public.shared_records)=0,'old records disappear for remaining partner');
select pg_temp.assert_switch((select count(*) from storage.objects where bucket_id='pipo-shared-images' and name=(select s1::text||'/'||photo::text||'.jpg' from switch_test))=0,'old picture access revoked');
update switch_test set s2=public.create_partner_space_with_role('user_1');
update switch_test set code=public.issue_pair_code()->>'code';
select pg_temp.assert_switch((select count(*) from public.shared_records)=0,'host new space starts empty');
select set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true) from switch_test;
select public.redeem_pair_code_with_role(code,'user_2') from switch_test;
select pg_temp.assert_switch((select count(*) from public.shared_records)=0,'new partner sees empty workspace');
select pg_temp.assert_switch((select count(*) from public.care_shares)=0,'new partner cannot see previous shared care');
select pg_temp.assert_switch((select count(*) from storage.objects where bucket_id='pipo-shared-images' and name=(select s1::text||'/'||photo::text||'.jpg' from switch_test))=0,'new partner cannot see previous image');
-- Both members can build new work together in the fresh space.
select public.mutate_shared_record(gen_random_uuid(),s2,'tag',null,null,'{"name":"New together"}'::jsonb,0,gen_random_uuid(),false) from switch_test;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true) from switch_test;
select pg_temp.assert_switch((select count(*) from public.shared_records)=1,'host sees new partner contribution');
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true) from switch_test;
update switch_test set s3=public.create_partner_space_with_role('user_1');
update switch_test set code=public.issue_pair_code()->>'code';
select pg_temp.assert_switch((select count(*) from public.shared_records)=0,'former partner also gets a fresh space');
select set_config('request.jwt.claims',jsonb_build_object('sub',d,'role','authenticated')::text,true) from switch_test;
select public.redeem_pair_code_with_role(code,'user_2') from switch_test;
select pg_temp.assert_switch((select count(*) from public.shared_records)=0,'second new partner starts empty');
select pg_temp.assert_switch((select count(*) from storage.objects where bucket_id='pipo-shared-images' and name=(select s1::text||'/'||photo::text||'.jpg' from switch_test))=0,'second couple cannot read old images');
reset role;
select pg_temp.assert_switch(s1<>s2 and s1<>s3 and s2<>s3,'couple IDs are unique') from switch_test;
select 'PASS: A+B close; both lose old records/images/care; A+C and B+D start fresh; new work is shared only within the new couple' as result;
rollback;
